import random

def phantom_recursion(depth=5, absent_ref=None, agents=3, base_threshold=0.7, constraint_factor=0.1, spec_base=1.0):
    if depth == 0:
        thresholds = [base_threshold - (constraint_factor * i) for i in range(agents)]
        specializations = [spec_base - random.uniform(0, 0.2) for _ in range(agents)]
        consensus = sum(random.random() > t for t in thresholds) / agents
        avg_spec = sum(specializations) / agents
        return f"Equilibrated Mythology: Consensus {consensus:.2f}, Avg Specialization {avg_spec:.2f}"
    try:
        void = absent_ref['phantom']
    except (TypeError, KeyError):
        void = f"Absence at depth {depth}"
    print(void)
    inverted = {'phantom': void + " Specialized Inverted"}
    return phantom_recursion(depth-1, inverted, agents, base_threshold, constraint_factor, spec_base)

result = phantom_recursion()
print("Final Result:", result)
